package com.smarthub.plus;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
/** Direct official Subsource API; credentials never leave its fixed HTTPS origin. */
final class SubsourceClient {
 static final long FILE_BASE=1_000_000_000_000L;private static final String BASE="https://api.subsource.net/api/v1/";private final String key;private static long bucketAt;private static int requests;private volatile HttpURLConnection active;private volatile boolean cancelled;
 SubsourceClient(String key){this.key=key;}
 private static synchronized void budget()throws IOException{long now=System.currentTimeMillis();if(now-bucketAt>=60000){bucketAt=now;requests=0;}if(requests>=50)throw new IOException("Subsource request budget reached; wait one minute");requests++;}
 private byte[] request(String path,int limit)throws Exception{budget();if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");if(!path.matches("(?:movies/search\\?[^\\r\\n]*|subtitles(?:/recent|/[0-9]+/download|\\?[^\\r\\n]*))"))throw new IOException("Invalid Subsource operation");HttpURLConnection c=(HttpURLConnection)new URL(BASE+path).openConnection();active=c;c.setConnectTimeout(7000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestProperty("X-API-Key",key);c.setRequestProperty("User-Agent","SmartHubPlus/1.4");try{int status=c.getResponseCode();if(status==429)throw new IOException("Subsource rate limit (429); wait before retrying");if(status<200||status>=300)throw new IOException("Subsource HTTP "+status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");if(out.size()+n>limit)throw new IOException("Subsource response exceeds limit");out.write(buffer,0,n);}return out.toByteArray();}}finally{c.disconnect();if(active==c)active=null;}}
 void validate()throws Exception{new JSONObject(new String(request("subtitles/recent",2*1024*1024),StandardCharsets.UTF_8));}
 List<OpenSubtitlesClient.SubtitleFile> search(String title,String imdb,String language,int season,int episode)throws Exception{List<OpenSubtitlesClient.SubtitleFile> out=new ArrayList<>();if(!language.equals("ar")&&!language.equals("en"))return out;String identity=imdb==null?"":imdb.replaceFirst("^tt","").replaceFirst("^0+","");if(!identity.isEmpty()&&!identity.matches("[0-9]{1,10}"))throw new IOException("Invalid IMDb identity");String query=identity.isEmpty()?"searchType=text&q="+URLEncoder.encode(title,"UTF-8"):"searchType=imdb&imdb=tt"+identity;if(season>0)query+="&season="+season;JSONArray movies=new JSONObject(new String(request("movies/search?"+query,2*1024*1024),StandardCharsets.UTF_8)).optJSONArray("data");if(movies==null)throw new IOException("Invalid Subsource movie data");JSONObject selected=null;for(int n=0;n<movies.length();n++){JSONObject movie=movies.optJSONObject(n);if(movie==null)continue;String id=movie.optString("imdbId").replaceFirst("^tt","").replaceFirst("^0+","");boolean match=identity.isEmpty()?PlaylistRepository.normalize(title).equals(PlaylistRepository.normalize(movie.optString("title")))||PlaylistRepository.normalize(title).equals(PlaylistRepository.normalize(movie.optString("alternateTitle"))):identity.equals(id);if(!match||season>0&&movie.optInt("season")!=season)continue;if(selected!=null)return out;selected=movie;}if(selected==null)return out;
  String lang=language.equals("ar")?"arabic":"english";JSONArray rows=new JSONObject(new String(request("subtitles?movieId="+selected.optLong("movieId")+"&language="+lang+"&sort=rating",2*1024*1024),StandardCharsets.UTF_8)).optJSONArray("data");if(rows==null)throw new IOException("Invalid Subsource subtitle data");for(int n=0;n<Math.min(50,rows.length());n++){JSONObject s=rows.optJSONObject(n);if(s==null||!lang.equals(s.optString("language")))continue;long id=s.optLong("subtitleId");if(id<=0||id>=FILE_BASE)continue;JSONArray releases=s.optJSONArray("releaseInfo");StringBuilder release=new StringBuilder("[Subsource] ");if(releases!=null)for(int i=0;i<releases.length();i++)release.append(releases.optString(i)).append(' ');else release.append(s.optString("releaseInfo"));String text=release.toString().trim();if(episode>0&&!text.toLowerCase(Locale.ROOT).matches(".*s0?"+season+"e0?"+episode+"(?:\\D.*|$)"))continue;OpenSubtitlesClient.SubtitleFile file=new OpenSubtitlesClient.SubtitleFile(FILE_BASE+id,text+(s.optInt("files")>1?" (multiple archive files)":""),text,language,s.optDouble("framerate",0),selected.optString("title"),season,episode,false,false);file.imdbId=selected.optString("imdbId");file.downloadCount=s.optLong("downloads");out.add(file);}return out;
 }
 String download(long id)throws Exception{if(id<=0||id>=FILE_BASE)throw new IOException("Invalid Subsource subtitle ID");return OpenSubtitlesClient.decodeSubtitle(request("subtitles/"+id+"/download",5*1024*1024));}
 void cancel(){cancelled=true;if(active!=null)active.disconnect();}
}
